toolArgs.file_text:
.chat-container {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* Sidebar */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #1a1d21;
    color: #ccc;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #333;
}

.sidebar-header {
    padding: 16px;
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
    border-bottom: 1px solid #333;
}

.channel-list {
    list-style: none;
    margin: 0;
    padding: 8px 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 10px 16px;
    cursor: pointer;
    position: relative;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #2c2f33;
}

.channel-item.active {
    background: #394b59;
    border-left: 3px solid #4a9eff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    color: #fff;
}

.channel-description {
    font-size: 0.78rem;
    color: #999;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: #e74c3c;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 7px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* Main Message Area */
.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #fff;
    min-width: 0;
}

.message-area.thread-open {
    max-width: 55%;
}

.message-header {
    padding: 12px 20px;
    border-bottom: 1px solid #e0e0e0;
    background: #fafafa;
}

.message-header h2 {
    margin: 0;
    font-size: 1.2rem;
    color: #1a1a1a;
}

.message-header p {
    margin: 4px 0 0;
    font-size: 0.85rem;
    color: #666;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #888;
    font-size: 0.85rem;
}

.message-item {
    position: relative;
    padding: 8px 12px;
    margin-bottom: 4px;
    border-radius: 6px;
    transition: background 0.1s;
}

.message-item:hover {
    background: #f5f5f5;
}

.message-meta {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.message-author {
    font-weight: 700;
    font-size: 0.9rem;
    color: #1a1a1a;
}

.message-time {
    font-size: 0.75rem;
    color: #999;
}

.message-text {
    font-size: 0.92rem;
    color: #333;
    line-height: 1.4;
    white-space: pre-wrap;
}

.reaction-row {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 6px;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 3px;
    padding: 2px 8px;
    background: #f0f4ff;
    border: 1px solid #d0d8e8;
    border-radius: 12px;
    font-size: 0.8rem;
    cursor: default;
}

.thread-link {
    display: inline-block;
    margin-top: 4px;
    font-size: 0.8rem;
    color: #4a9eff;
    cursor: pointer;
    text-decoration: none;
}

.thread-link:hover {
    text-decoration: underline;
}

/* Message Actions */
.message-actions {
    position: absolute;
    top: 4px;
    right: 8px;
    display: flex;
    gap: 4px;
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 2px 4px;
    box-shadow: 0 2px 6px rgba(0,0,0,0.1);
}

.action-btn {
    border: none;
    background: transparent;
    cursor: pointer;
    font-size: 1rem;
    padding: 4px 6px;
    border-radius: 4px;
    transition: background 0.1s;
}

.action-btn:hover {
    background: #f0f0f0;
}

/* Emoji Picker */
.emoji-picker {
    display: flex;
    gap: 4px;
    margin-top: 6px;
    padding: 6px 8px;
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.12);
    width: fit-content;
}

.emoji-option {
    border: none;
    background: transparent;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 6px;
    border-radius: 4px;
    transition: background 0.1s;
}

.emoji-option:hover {
    background: #f0f0f0;
}

/* Message Input */
.message-input-area {
    display: flex;
    align-items: flex-end;
    gap: 8px;
    padding: 12px 20px;
    border-top: 1px solid #e0e0e0;
    background: #fafafa;
}

.message-input-area textarea {
    flex: 1;
    resize: none;
    border: 1px solid #ccc;
    border-radius: 8px;
    padding: 10px 12px;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
    transition: border-color 0.15s;
}

.message-input-area textarea:focus {
    border-color: #4a9eff;
}

.send-btn {
    padding: 10px 20px;
    background: #4a9eff;
    color: #fff;
    border: none;
    border-radius: 8px;
    font-weight: 600;
    font-size: 0.9rem;
    cursor: pointer;
    transition: background 0.15s;
}

.send-btn:hover:not(:disabled) {
    background: #3580d4;
}

.send-btn:disabled {
    background: #b0c4de;
    cursor: not-allowed;
}

/* No Channel Selected */
.no-channel-selected {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #999;
    font-size: 1.1rem;
}

/* Thread Panel */
.thread-panel {
    width: 25%;
    min-width: 280px;
    display: flex;
    flex-direction: column;
    border-left: 1px solid #e0e0e0;
    background: #fafbfc;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #e0e0e0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
}

.close-thread-btn {
    border: none;
    background: transparent;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    color: #666;
}

.close-thread-btn:hover {
    background: #e0e0e0;
}

.thread-root-quote {
    padding: 12px 16px;
    background: #f0f4ff;
    border-bottom: 1px solid #e0e0e0;
    font-size: 0.88rem;
}

.thread-root-quote p {
    margin: 4px 0 0;
    color: #444;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

